namespace LiveScore.BetRadarSimulator.Controllers
{
    using Fanex.Logging;
    using LiveScore.BetRadarSimulator.Api.Services;
    using LiveScore.BetRadarSimulator.Results;
    using LiveScore.BetRadarSimulator.Services;
    using LiveScore.Providers.SportRadar.Dtos;
    using Microsoft.AspNetCore.Mvc;
    using Microsoft.Extensions.Configuration;
    using Newtonsoft.Json;
    using System;
    using System.Collections.Generic;
    using System.IO;
    using System.Threading;
    using System.Threading.Tasks;
    using System.Timers;

    [Route("api/[controller]")]
    [ApiController]
    public class EventsController : ControllerBase
    {
        private const int DefaultInterval = 5 * 1000;
        private const string HeartBeat = "{\"heartbeat\":{\"interval\":5000}} \n";
        private const string AppSettingPath = "BetRadarSimulator:ApiUrl";

        private static System.Timers.Timer timer;
        private INotificationService notificationService;
        private readonly IConfiguration configuration;
        private readonly ILogger logger;

        public EventsController(INotificationService notificationService, IConfiguration configuration, ILogger logger)
        {
            this.notificationService = notificationService;
            this.configuration = configuration;
            this.logger = logger;
        }

        [Route("~/api/{sportType}-{accessLevel}/{region}/stream/events/subscribe/")]
        [HttpGet]
        public IActionResult Subscribe(string sportType, string accessLevel, string region)
        {
            var host = configuration.GetSection(AppSettingPath);

            return Redirect($"{host.Value}events/Stat");
        }

        [Route("~/api/{sportType}-{accessLevel}/{region}/stream/events/stat/")]
        [HttpGet()]
        public IActionResult Stat(string sportType, string accessLevel, string region)
        {
            if (timer == null)
            {
                timer = new System.Timers.Timer();
                timer.Interval = DefaultInterval;
                timer.AutoReset = true;
                timer.Elapsed += TimerElapsed;
                timer.Start();
            }

            return new PushStreamResult(OnStreamAvailabe, HttpContext.RequestAborted);
        }

        [HttpPost(nameof(Push))]
        public async Task<IActionResult> Push(string eventStr)
        {
            await SendEvent(eventStr);

            return Ok();
        }

        [Route("~/api/{sportType}-{accessLevel}/{region}/stream/events/pushevent/")]
        [HttpPost()]
        public async Task<IActionResult> PushEvent(
            string sportType,
            string accessLevel,
            string region,
            [FromBody] MatchPushEventDto pushEvent)
        {
            try
            {
                var eventStr = JsonConvert.SerializeObject(pushEvent);

                await SendEvent(eventStr);
            }
            catch (Exception ex)
            {
                await logger.ErrorAsync($"{DateTime.Now} SendEvent Error ", ex);
            }

            return Ok();
        }

        [Route("~/api/{sportType}-{accessLevel}/{region}/stream/events/pushevents/")]
        [HttpPost()]
        public async Task<IActionResult> PushEvents(
            string sportType,
            string accessLevel,
            string region,
            [FromBody] IList<MatchPushEventDto> pushEvents)
        {
            try
            {
                var eventStr = string.Empty;

                foreach (var pushEvent in pushEvents)
                {
                    eventStr += JsonConvert.SerializeObject(pushEvent);
                }

                await SendEvent(eventStr);
            }
            catch (Exception ex)
            {
                await logger.ErrorAsync($"{DateTime.Now} PushEvents Error ", ex);
            }

            return Ok();
        }

        [HttpGet(nameof(GetTotalOfClients))]
        public int GetTotalOfClients() => notificationService.GetClients().Count;

        private void OnStreamAvailabe(Stream stream, CancellationToken requestAborted)
        {
            var wait = requestAborted.WaitHandle;
            var client = new ServerSentEventsClient(stream);
            notificationService.AddClient(client);
            logger.Info($"{DateTime.Now} Add new client {client.Id} ");

            wait.WaitOne();

            notificationService.RemoveClient(client);
        }

        private async void TimerElapsed(object sender, ElapsedEventArgs e)
        {
            foreach (var client in notificationService.GetClients())
            {
                try
                {
                    await client.SendEventAsync(HeartBeat);
                }
                catch (Exception ex)
                {
                    await logger.ErrorAsync($"{DateTime.Now} SendEvent Error ", ex);

                    notificationService.RemoveClient(client);
                }
            }
        }

        private async Task SendEvent(string eventstr)
        {
            var clients = notificationService.GetClients();

            await logger.InfoAsync($"{DateTime.Now} SendEvent {eventstr} to {clients.Count} clients");

            foreach (var client in clients)
            {
                var data = $"{eventstr} {Environment.NewLine}";

                await client.SendEventAsync(data);
            }
        }
    }
}
